/**
 * The shared fluid classes of an ejected project (ADR 0099 D1, D2, ADR 0108 D1 to D3, ADR 0112
 * D3), copied from the runtime's `registry/fluid/` (`MsmFluids`, `MsmLiquidBlock`, `FluidMixing`,
 * `MsmCauldronBlock`, `MsmCauldrons`, `MsmBottleItem`), the 26.3 seam (`MsmFluid`,
 * `MsmFlowingFluid`) and `client/fluid/FluidClient`, with the runtime's parsed `FluidDefinition`
 * replaced by `FluidSpec`, a record the generated `ModFluids` builds from each definition, and the
 * runtime's event runner by the `FluidSpec.Inside` and `Drink` hooks the generated per-fluid
 * events classes implement. Logic and numbers are the runtime's line for line; the targets tests
 * compare the code lines with the runtime sources.
 *
 * Minecraft 26.3, Mojang names.
 *
 * @packageDocumentation
 */

import { javaString } from '../java';

/** `fluid/FluidSpec.java`: a fluid definition with every default resolved (the runtime's `FluidDefinition`). */
export function fluidSpecJava(fluidPackage: string): string {
  return `// Generated by MCSuperMods: msm_runtime's FluidDefinition as a plain record.
package ${fluidPackage};

import java.util.List;
import net.minecraft.core.BlockPos;
import net.minecraft.resources.Identifier;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.entity.Entity;
import net.minecraft.world.entity.LivingEntity;

/**
 * One fluid (ADR 0099 D1, ADR 0108) with every default resolved.
 *
 * @param behavesLike         which vanilla liquid entities treat it like
 * @param tickDelay           ticks between two flow steps
 * @param slopeDistance       how far flowing fluid looks for a way down
 * @param dropOff             levels lost per block of spreading
 * @param infinite            whether two sources beside each other make a new source
 * @param light               the liquid block's light level
 * @param tint                an RGB colour multiplied over the pictures on the client; -1 for none
 * @param explosionResistance of the fluid and its liquid block
 * @param mixing              what forms where this fluid meets another, in file order
 * @param cauldron            the cauldron companion, or null
 * @param bottle              the bottle companion, or null
 * @param inside              the on_entity_inside event, or null
 * @param drink               the bottle's on_drink event, or null
 */
public record FluidSpec(Behaviour behavesLike, int tickDelay, int slopeDistance, int dropOff, boolean infinite, int light, int tint,
        float explosionResistance, List<Mixing> mixing, Cauldron cauldron, Bottle bottle, Inside inside, Drink drink) {
    /** Seconds a bottle takes to drink (ADR 0108 D3 as amended: a potion's 1.6, B525). */
    public static final float BOTTLE_DRINK_SECONDS = 1.6f;
    /** Ticks between two {@code on_entity_inside} firings for the same entity (ADR 0099 D1, ADR 0061 D2). */
    public static final int INSIDE_COOLDOWN_TICKS = 10;

    /** {@code behaves_like}. */
    public enum Behaviour {
        WATER, LAVA, NONE
    }

    /**
     * A mixing rule (ADR 0108 D1 as amended): when this fluid meets {@code withTag} (vanilla's water or lava tag) or
     * exactly {@code withFluid}, its touched source becomes {@code source} and its flowing fluid {@code flowing}.
     */
    public record Mixing(Behaviour withTag, Identifier withFluid, Identifier source, Identifier flowing) {}

    /** The cauldron (ADR 0108 D2): {@code levels} fills in three levels as water's, else full only as lava's. */
    public record Cauldron(boolean levels) {}

    /** Hunger a bottle restores. */
    public record Food(int nutrition, float saturation, boolean canAlwaysEat) {}

    /** A mob effect a bottle gives. */
    public record Effect(Identifier effect, int ticks, int amplifier, float chance) {}

    /** The bottle (ADR 0108 D3); {@code food} null for none. */
    public record Bottle(Food food, List<Effect> effects) {}

    /** The fluid's on_entity_inside event. */
    @FunctionalInterface
    public interface Inside {
        void fire(ServerLevel level, BlockPos pos, Entity entity);
    }

    /** The bottle's on_drink event (self the drinker). */
    @FunctionalInterface
    public interface Drink {
        void fire(ServerLevel level, LivingEntity drinker);
    }
}
`;
}

/** `fluid/FluidRegistry.java`: the runtime's `MsmFluids` (registration and shared behaviour). */
export function fluidRegistryJava(fluidPackage: string, modId: string): string {
  return `// Generated by MCSuperMods: msm_runtime's MsmFluids as a plain helper.
package ${fluidPackage};

import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import net.fabricmc.fabric.api.creativetab.v1.CreativeModeTabEvents;
import net.minecraft.core.BlockPos;
import net.minecraft.core.Registry;
import net.minecraft.core.dispenser.DispenseItemBehavior;
import net.minecraft.core.registries.BuiltInRegistries;
import net.minecraft.core.registries.Registries;
import net.minecraft.resources.Identifier;
import net.minecraft.resources.ResourceKey;
import net.minecraft.sounds.SoundEvent;
import net.minecraft.sounds.SoundEvents;
import net.minecraft.world.entity.Entity;
import net.minecraft.world.entity.InsideBlockEffectApplier;
import net.minecraft.world.entity.InsideBlockEffectType;
import net.minecraft.world.item.BucketItem;
import net.minecraft.world.item.CreativeModeTab;
import net.minecraft.world.item.Item;
import net.minecraft.world.item.Items;
import net.minecraft.world.level.LevelAccessor;
import net.minecraft.world.level.block.Block;
import net.minecraft.world.level.block.DispenserBlock;
import net.minecraft.world.level.block.entity.BlockEntity;
import net.minecraft.world.level.block.state.BlockBehaviour;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.level.material.FlowingFluid;
import net.minecraft.world.level.material.Fluid;
import net.minecraft.world.level.material.MapColor;
import net.minecraft.world.level.material.PushReaction;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * The fluids (ADR 0099 D1, D2): per fluid, the still fluid {@code <id>} and the flowing fluid {@code <ns>:flowing_<path>},
 * the {@link ModLiquidBlock} under the fluid's id and the {@link BucketItem} {@code <ns>:<path>_bucket}. Flow, sources,
 * draining and buckets are vanilla's; dispensers use vanilla's own filled-bucket behaviour; the bucket goes into vanilla's
 * Tools and Utilities tab. A taken id is logged and that fluid is not registered.
 */
public final class FluidRegistry {
    private static final Logger LOGGER = LoggerFactory.getLogger(${javaString(modId)});
    /** The vanilla tab the buckets join (vanilla's buckets are there). */
    static final ResourceKey<CreativeModeTab> BUCKET_TAB =
            ResourceKey.create(Registries.CREATIVE_MODE_TAB, Identifier.withDefaultNamespace("tools_and_utilities"));

    private FluidRegistry() {}

    /** The fluids one definition registers: the source (a bucket holds it), the still and the flowing entry. */
    public record Fluids(FlowingFluid source, Fluid still, Fluid flowing) {}

    /** One registered fluid. */
    public record Entry(Identifier id, FluidSpec spec, Fluids fluids, ModLiquidBlock block, BucketItem bucket) {}

    private static final Map<Identifier, Entry> REGISTERED = new LinkedHashMap<>();

    /** Every fluid registered so far, in registration order. */
    public static List<Entry> registered() {
        return List.copyOf(REGISTERED.values());
    }

    /** The fluid registered under {@code id}, if any. */
    public static Optional<Entry> get(Identifier id) {
        return Optional.ofNullable(REGISTERED.get(id));
    }

    /** The bucket item id of a fluid: {@code <ns>:<path>_bucket}. */
    public static Identifier bucketId(Identifier id) {
        return id.withSuffix("_bucket");
    }

    /** The flowing fluid's id: {@code flowing_} before the last path segment. */
    public static Identifier flowingId(Identifier id) {
        String path = id.getPath();
        int slash = path.lastIndexOf('/');
        return id.withPath(path.substring(0, slash + 1) + "flowing_" + path.substring(slash + 1));
    }

    /** Registers one fluid with its liquid block and bucket; a taken id is logged and nothing is registered. */
    public static void register(Identifier id, FluidSpec spec) {
        String clash = clash(id);
        if (clash != null) {
            LOGGER.error("fluid {}: {}; the fluid is not registered", id, clash);
            return;
        }
        DispenseItemBehavior dispense = DispenserBlock.DISPENSER_REGISTRY.get(Items.WATER_BUCKET);
        if (dispense == null) {
            LOGGER.warn("fluid {}: vanilla's water bucket has no dispenser behaviour yet; the bucket is dropped by dispensers", id);
        }
        ResourceKey<Block> blockKey = ResourceKey.create(Registries.BLOCK, id);
        ResourceKey<Item> bucketKey = ResourceKey.create(Registries.ITEM, bucketId(id));
        // The fluids are made first and reach their block and bucket through these holders, set right below.
        Block[] block = new Block[1];
        Item[] bucket = new Item[1];
        Fluids fluids = ModFluid.register(id, spec, () -> block[0], () -> bucket[0]);
        int light = spec.light();
        BlockBehaviour.Properties props = BlockBehaviour.Properties.of()
                .setId(blockKey)
                .mapColor(switch (spec.behavesLike()) {
                    case WATER -> MapColor.WATER;
                    case LAVA -> MapColor.FIRE;
                    case NONE -> MapColor.NONE;
                })
                .replaceable()
                .noCollision()
                .strength(100.0f, spec.explosionResistance())
                .pushReaction(PushReaction.POPPED)
                .noLootTable()
                .liquid()
                .lightLevel(state -> light);
        ModLiquidBlock liquid = Registry.register(BuiltInRegistries.BLOCK, blockKey, new ModLiquidBlock(fluids.source(), props, id, spec));
        block[0] = liquid;
        BucketItem item = Registry.register(BuiltInRegistries.ITEM, bucketKey,
                new BucketItem(fluids.source(), new Item.Properties().setId(bucketKey).craftRemainder(Items.BUCKET).stacksTo(1)));
        bucket[0] = item;
        if (dispense != null) {
            DispenserBlock.registerBehavior(item, dispense);
        }
        CreativeModeTabEvents.modifyOutputEvent(BUCKET_TAB).register(output -> output.accept(item));
        REGISTERED.put(id, new Entry(id, spec, fluids, liquid, item));
    }

    /** Why {@code id} cannot be registered as a fluid, or null when every id it needs is free. */
    private static String clash(Identifier id) {
        for (Identifier fluid : List.of(id, flowingId(id))) {
            if (BuiltInRegistries.FLUID.containsKey(fluid)) {
                return "fluid id " + fluid + " is already registered";
            }
        }
        if (BuiltInRegistries.BLOCK.containsKey(id)) {
            return "block id " + id + " (the liquid block) is already registered";
        }
        if (BuiltInRegistries.ITEM.containsKey(bucketId(id))) {
            return "item id " + bucketId(id) + " (the bucket) is already registered";
        }
        return null;
    }

    /** The fluid's own effects on an entity inside it: water-like puts fire out, lava-like sets on fire and hurts. */
    public static void insideEffects(FluidSpec spec, InsideBlockEffectApplier effects) {
        switch (spec.behavesLike()) {
            case WATER -> effects.apply(InsideBlockEffectType.EXTINGUISH);
            case LAVA -> {
                effects.apply(InsideBlockEffectType.LAVA_IGNITE);
                effects.runAfter(InsideBlockEffectType.LAVA_IGNITE, Entity::lavaHurt);
            }
            case NONE -> {}
        }
    }

    /** The sound a bucket makes picking the fluid up: lava's for lava-like, else water's. */
    public static SoundEvent pickupSound(FluidSpec spec) {
        return spec.behavesLike() == FluidSpec.Behaviour.LAVA ? SoundEvents.BUCKET_FILL_LAVA : SoundEvents.BUCKET_FILL;
    }

    /** What a flowing fluid does to a block it replaces: the block drops its loot, as when water washes a torch away. */
    public static void beforeDestroyingBlock(LevelAccessor level, BlockPos pos, BlockState state) {
        BlockEntity entity = state.hasBlockEntity() ? level.getBlockEntity(pos) : null;
        Block.dropResources(state, level, pos, entity);
    }

}
`;
}

/** `fluid/ModFluid.java` and `fluid/ModFlowingFluid.java`: the 26.3 `MsmFluid` seam (two fluids per liquid). */
export function modFluidJava(fluidPackage: string): string {
  return `// Generated by MCSuperMods: msm_runtime's 26.3 MsmFluid as a plain class.
package ${fluidPackage};

import java.util.Optional;
import java.util.function.Supplier;
import net.minecraft.core.BlockPos;
import net.minecraft.core.Direction;
import net.minecraft.core.Registry;
import net.minecraft.core.registries.BuiltInRegistries;
import net.minecraft.resources.Identifier;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.sounds.SoundEvent;
import net.minecraft.world.entity.Entity;
import net.minecraft.world.entity.InsideBlockEffectApplier;
import net.minecraft.world.item.Item;
import net.minecraft.world.level.BlockGetter;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.LevelAccessor;
import net.minecraft.world.level.LevelReader;
import net.minecraft.world.level.block.Block;
import net.minecraft.world.level.block.LiquidBlock;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.level.material.FlowingFluid;
import net.minecraft.world.level.material.Fluid;
import net.minecraft.world.level.material.FluidState;

/**
 * The still (source) fluid of a liquid, registered as {@code <id>}; {@link ModFlowingFluid} is the flowing one,
 * registered as {@code <ns>:flowing_<path>}. Both read the same {@link FluidSpec}; everything else is vanilla's
 * {@code FlowingFluid}. Swimming, drowning and fog come from the fluid tags (data).
 */
public class ModFluid extends FlowingFluid {
    /** The two fluids of one liquid, linked once both exist. */
    static final class Pair {
        ModFluid source;
        ModFlowingFluid flowing;
    }

    final FluidSpec spec;
    final Pair pair;
    final Supplier<Block> block;
    final Supplier<Item> bucket;

    ModFluid(FluidSpec spec, Pair pair, Supplier<Block> block, Supplier<Item> bucket) {
        this.spec = spec;
        this.pair = pair;
        this.block = block;
        this.bucket = bucket;
    }

    /** Registers the source and the flowing fluid of {@code id}; {@code block} and {@code bucket} are read only once the game asks. */
    static FluidRegistry.Fluids register(Identifier id, FluidSpec spec, Supplier<Block> block, Supplier<Item> bucket) {
        Pair pair = new Pair();
        pair.source = new ModFluid(spec, pair, block, bucket);
        pair.flowing = new ModFlowingFluid(spec, pair, block, bucket);
        Registry.register(BuiltInRegistries.FLUID, id, pair.source);
        Registry.register(BuiltInRegistries.FLUID, FluidRegistry.flowingId(id), pair.flowing);
        return new FluidRegistry.Fluids(pair.source, pair.source, pair.flowing);
    }

    @Override
    public Fluid getFlowing() {
        return pair.flowing;
    }

    @Override
    public Fluid getSource() {
        return pair.source;
    }

    @Override
    public Item getBucket() {
        return bucket.get();
    }

    @Override
    public boolean isSame(Fluid fluid) {
        return fluid == pair.source || fluid == pair.flowing;
    }

    @Override
    protected boolean canConvertToSource(ServerLevel level) {
        return spec.infinite();
    }

    @Override
    protected void beforeDestroyingBlock(LevelAccessor level, BlockPos pos, BlockState state) {
        FluidRegistry.beforeDestroyingBlock(level, pos, state);
    }

    /** Falling into another liquid a mixing rule names makes the rule's {@code flowing} block there ({@link FluidMixing#fallInto}). */
    @Override
    protected void spreadTo(LevelAccessor level, BlockPos pos, BlockState state, Direction direction, FluidState fluid) {
        if (!FluidMixing.fallInto(block.get(), level, pos, direction)) {
            super.spreadTo(level, pos, state, direction, fluid);
        }
    }

    @Override
    protected int getSlopeFindDistance(LevelReader level) {
        return spec.slopeDistance();
    }

    @Override
    protected int getDropOff(LevelReader level) {
        return spec.dropOff();
    }

    @Override
    public int getTickDelay(LevelReader level) {
        return spec.tickDelay();
    }

    @Override
    protected boolean canBeReplacedWith(FluidState state, BlockGetter level, BlockPos pos, Fluid other, Direction direction) {
        return direction == Direction.DOWN && !isSame(other);
    }

    @Override
    protected float getExplosionResistance() {
        return spec.explosionResistance();
    }

    @Override
    protected BlockState createLegacyBlock(FluidState state) {
        return block.get().defaultBlockState().setValue(LiquidBlock.LEVEL, getLegacyLevel(state));
    }

    @Override
    protected void entityInside(Level level, BlockPos pos, Entity entity, InsideBlockEffectApplier effects) {
        FluidRegistry.insideEffects(spec, effects);
    }

    @Override
    public Optional<SoundEvent> getPickupSound() {
        return Optional.of(FluidRegistry.pickupSound(spec));
    }

    @Override
    public boolean isSource(FluidState state) {
        return true;
    }

    @Override
    public int getAmount(FluidState state) {
        return 8;
    }
}
`;
}

/** `fluid/ModFlowingFluid.java`. */
export function modFlowingFluidJava(fluidPackage: string): string {
  return `// Generated by MCSuperMods: msm_runtime's 26.3 MsmFlowingFluid as a plain class.
package ${fluidPackage};

import java.util.function.Supplier;
import net.minecraft.world.item.Item;
import net.minecraft.world.level.block.Block;
import net.minecraft.world.level.block.state.StateDefinition;
import net.minecraft.world.level.material.Fluid;
import net.minecraft.world.level.material.FluidState;

/** The flowing fluid of a liquid, registered as {@code <ns>:flowing_<path>}: it carries a {@code level} and is never a source. */
public final class ModFlowingFluid extends ModFluid {
    ModFlowingFluid(FluidSpec spec, Pair pair, Supplier<Block> block, Supplier<Item> bucket) {
        super(spec, pair, block, bucket);
    }

    @Override
    protected void createFluidStateDefinition(StateDefinition.Builder<Fluid, FluidState> builder) {
        super.createFluidStateDefinition(builder);
        builder.add(LEVEL);
    }

    @Override
    public boolean isSource(FluidState state) {
        return false;
    }

    @Override
    public int getAmount(FluidState state) {
        return state.getValue(LEVEL);
    }
}
`;
}

/** `fluid/ModLiquidBlock.java`: the runtime's `MsmLiquidBlock`. */
export function modLiquidBlockJava(fluidPackage: string, modPackage: string): string {
  return `// Generated by MCSuperMods: msm_runtime's MsmLiquidBlock as a plain class.
package ${fluidPackage};

import ${modPackage}.CooldownMap;
import ${modPackage}.TickLimiter;
import net.minecraft.core.BlockPos;
import net.minecraft.resources.Identifier;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.entity.Entity;
import net.minecraft.world.entity.InsideBlockEffectApplier;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.block.Block;
import net.minecraft.world.level.block.LiquidBlock;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.level.material.FlowingFluid;
import net.minecraft.world.level.redstone.Orientation;

/**
 * The liquid block of a fluid (ADR 0099 D1): vanilla's {@code LiquidBlock} plus {@code on_entity_inside}, fired on the
 * server at most every {@link FluidSpec#INSIDE_COOLDOWN_TICKS} ticks for the same entity however many of the fluid's blocks
 * it touches, under the shared tick cap. With {@code mixing}, {@link #onPlace} and {@link #neighborChanged} run
 * {@link FluidMixing}'s own check and, when nothing mixed, only schedule the fluid tick (ADR 0108 D1 as amended).
 */
public final class ModLiquidBlock extends LiquidBlock {
    /** Where every entity's cooldown is kept: one entry per entity and dimension, not per block. */
    private static final BlockPos ANY_BLOCK = BlockPos.ZERO;

    private final Identifier id;
    private final FluidSpec spec;
    /** {@code on_entity_inside} cooldowns per dimension and entity. Server thread only. */
    private final CooldownMap insideCooldowns = new CooldownMap();

    ModLiquidBlock(FlowingFluid fluid, Properties properties, Identifier id, FluidSpec spec) {
        super(fluid, properties);
        this.id = id;
        this.spec = spec;
    }

    public Identifier id() {
        return id;
    }

    public FluidSpec spec() {
        return spec;
    }

    @Override
    protected void onPlace(BlockState state, Level level, BlockPos pos, BlockState old, boolean movedByPiston) {
        if (!FluidMixing.hasRules(this)) {
            super.onPlace(state, level, pos, old, movedByPiston);
        } else if (!FluidMixing.mix(this, level, pos, state)) {
            scheduleFluidTick(state, level, pos);
        }
    }

    @Override
    protected void neighborChanged(BlockState state, Level level, BlockPos pos, Block block, Orientation orientation, boolean movedByPiston) {
        if (!FluidMixing.hasRules(this)) {
            super.neighborChanged(state, level, pos, block, orientation, movedByPiston);
        } else if (!FluidMixing.mix(this, level, pos, state)) {
            scheduleFluidTick(state, level, pos);
        }
    }

    private void scheduleFluidTick(BlockState state, Level level, BlockPos pos) {
        level.scheduleTick(pos, state.getFluidState().getType(), fluid.getTickDelay(level));
    }

    @Override
    protected void entityInside(BlockState state, Level level, BlockPos pos, Entity entity, InsideBlockEffectApplier effects,
            boolean intersects) {
        super.entityInside(state, level, pos, entity, effects, intersects);
        fireInside(level, pos, entity);
    }

    /** {@code on_entity_inside} for an entity in this fluid or in its cauldron: one cooldown per entity for both. */
    void fireInside(Level level, BlockPos pos, Entity entity) {
        if (spec.inside() != null && level instanceof ServerLevel server
                && insideCooldowns.tryFire(server.dimension(), ANY_BLOCK, entity.getUUID(), server.getGameTime(),
                        FluidSpec.INSIDE_COOLDOWN_TICKS)
                && TickLimiter.tryFire(server)) {
            spec.inside().fire(server, pos.immutable(), entity);
        }
    }
}
`;
}

/** `fluid/FluidMixing.java`: the runtime's `FluidMixing`. */
export function fluidMixingJava(fluidPackage: string, modId: string): string {
  return `// Generated by MCSuperMods: msm_runtime's FluidMixing as a plain helper.
package ${fluidPackage};

import java.util.ArrayList;
import java.util.IdentityHashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import net.fabricmc.fabric.api.event.lifecycle.v1.ServerLifecycleEvents;
import net.minecraft.core.BlockPos;
import net.minecraft.core.Direction;
import net.minecraft.core.registries.BuiltInRegistries;
import net.minecraft.resources.Identifier;
import net.minecraft.tags.FluidTags;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.LevelAccessor;
import net.minecraft.world.level.block.Block;
import net.minecraft.world.level.block.LevelEvent;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.level.material.Fluid;
import net.minecraft.world.level.material.FluidState;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * Mixing of the fluids with water, lava and each other (ADR 0108 D1 and its amendment after B525). A liquid block with
 * {@code mixing} checks its five neighbours other than the one below when it is placed or a neighbour changes: when one
 * holds a fluid a rule names, a source becomes the rule's {@code source} block and a flowing block its {@code flowing}
 * block, with vanilla's lava fizz. The rules that name a fluid come before the {@code water} and {@code lava} rules; within
 * a rule the sides up, north, south, west and east. Liquids are compared by their liquid block. Falling into a liquid a rule
 * names makes the rule's {@code flowing} block there. The rules' blocks and fluids are looked up at server start; an unknown
 * block leaves that side out and an unknown fluid drops the rule, each with one warning.
 */
public final class FluidMixing {
    private static final Logger LOGGER = LoggerFactory.getLogger(${javaString(modId)});

    private FluidMixing() {}

    /** One rule with its ids looked up. */
    record Rule(FluidSpec.Behaviour tag, Block with, Block source, Block flowing) {
        boolean matches(FluidState other) {
            if (other.isEmpty()) {
                return false;
            }
            if (tag != null) {
                return other.is(tag == FluidSpec.Behaviour.WATER ? FluidTags.WATER : FluidTags.LAVA);
            }
            return other.createLegacyBlock().getBlock() == with;
        }

        Block result(boolean sourceFluid) {
            return sourceFluid ? source : flowing;
        }
    }

    private static boolean installed;
    /** The looked-up rules per liquid block with {@code mixing}, ids first. Rebuilt at every server start. */
    private static volatile Map<ModLiquidBlock, List<Rule>> rules = Map.of();

    /** Installs the server start lookup of the rules' blocks and fluids. */
    public static void register() {
        if (!installed) {
            installed = true;
            ServerLifecycleEvents.SERVER_STARTING.register(server -> resolve());
        }
    }

    /** Looks up every registered fluid's rules; logs a warning per unknown id. */
    static synchronized void resolve() {
        Map<ModLiquidBlock, List<Rule>> out = new IdentityHashMap<>();
        List<String> warnings = new ArrayList<>();
        for (FluidRegistry.Entry entry : FluidRegistry.registered()) {
            if (!entry.spec().mixing().isEmpty()) {
                out.put(entry.block(), compile(entry, warnings));
            }
        }
        warnings.forEach(LOGGER::warn);
        rules = out;
    }

    private static List<Rule> compile(FluidRegistry.Entry entry, List<String> warnings) {
        List<Rule> byId = new ArrayList<>();
        List<Rule> byTag = new ArrayList<>();
        List<FluidSpec.Mixing> mixing = entry.spec().mixing();
        for (int n = 0; n < mixing.size(); n++) {
            FluidSpec.Mixing m = mixing.get(n);
            String where = "fluid " + entry.id() + ": mixing[" + n + "]: ";
            Block with = null;
            if (m.withFluid() != null) {
                Identifier id = m.withFluid();
                Optional<Fluid> fluid = BuiltInRegistries.FLUID.getOptional(id);
                if (fluid.isEmpty() || fluid.get().defaultFluidState().isEmpty()) {
                    warnings.add(where + "with " + id + " is not a registered fluid; the rule is dropped");
                    continue;
                }
                with = fluid.get().defaultFluidState().createLegacyBlock().getBlock();
                if (with == entry.block()) {
                    warnings.add(where + "with " + id + " is this fluid itself; the rule is dropped");
                    continue;
                }
            }
            Block source = block(m.source(), where + "source", warnings);
            Block flowing = block(m.flowing(), where + "flowing", warnings);
            if (source == null && flowing == null) {
                continue;
            }
            Rule rule = new Rule(m.withTag(), with, source, flowing);
            (with != null ? byId : byTag).add(rule);
        }
        byId.addAll(byTag);
        return List.copyOf(byId);
    }

    private static Block block(Identifier id, String where, List<String> warnings) {
        if (id == null) {
            return null;
        }
        Optional<Block> block = BuiltInRegistries.BLOCK.getOptional(id);
        if (block.isEmpty()) {
            warnings.add(where + " " + id + " is not a registered block; that side is left out");
            return null;
        }
        return block.get();
    }

    /** The rules of {@code block}, looked up on first use when the server start has not done it. */
    static List<Rule> rulesOf(ModLiquidBlock block) {
        List<Rule> found = rules.get(block);
        if (found == null && !block.spec().mixing().isEmpty()) {
            resolve();
            found = rules.get(block);
        }
        return found == null ? List.of() : found;
    }

    /** Whether {@code block} mixes by its own rules (and so never runs vanilla's liquid checks). */
    static boolean hasRules(ModLiquidBlock block) {
        return !block.spec().mixing().isEmpty();
    }

    /** The liquid block's own check: true when the block at {@code pos} was replaced by a rule's block. Server side only. */
    static boolean mix(ModLiquidBlock block, Level level, BlockPos pos, BlockState state) {
        if (level.isClientSide()) {
            return false;
        }
        FluidState mine = state.getFluidState();
        if (mine.isEmpty()) {
            return false;
        }
        boolean source = mine.isSource();
        for (Rule rule : rulesOf(block)) {
            Block result = rule.result(source);
            if (result == null) {
                continue;
            }
            for (Direction d : Direction.values()) {
                if (d == Direction.DOWN) {
                    continue;
                }
                FluidState other = level.getFluidState(pos.relative(d));
                if (other.isEmpty() || other.createLegacyBlock().getBlock() == block) {
                    continue;
                }
                if (rule.matches(other)) {
                    level.setBlockAndUpdate(pos, result.defaultBlockState());
                    level.levelEvent(LevelEvent.LAVA_FIZZ, pos, 0);
                    return true;
                }
            }
        }
        return false;
    }

    /** Falling into another liquid (vanilla's lava falling into water); true when the rule's flowing block was set. */
    public static boolean fallInto(Block owner, LevelAccessor level, BlockPos pos, Direction direction) {
        if (direction != Direction.DOWN || !(owner instanceof ModLiquidBlock block) || !hasRules(block)) {
            return false;
        }
        FluidState other = level.getFluidState(pos);
        if (other.isEmpty() || other.createLegacyBlock().getBlock() == block) {
            return false;
        }
        for (Rule rule : rulesOf(block)) {
            if (rule.flowing() != null && rule.matches(other)) {
                level.setBlock(pos, rule.flowing().defaultBlockState(), Block.UPDATE_ALL);
                level.levelEvent(LevelEvent.LAVA_FIZZ, pos, 0);
                return true;
            }
        }
        return false;
    }
}
`;
}

/** `fluid/ModCauldronBlock.java` and `fluid/ModBottleItem.java` and `fluid/FluidCauldrons.java`. */
export function modCauldronBlockJava(fluidPackage: string): string {
  return `// Generated by MCSuperMods: msm_runtime's MsmCauldronBlock as plain classes.
package ${fluidPackage};

import net.minecraft.core.BlockPos;
import net.minecraft.core.Direction;
import net.minecraft.core.cauldron.CauldronInteraction;
import net.minecraft.world.InteractionHand;
import net.minecraft.world.InteractionResult;
import net.minecraft.world.entity.Entity;
import net.minecraft.world.entity.InsideBlockEffectApplier;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.item.Items;
import net.minecraft.world.level.BlockGetter;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.LevelReader;
import net.minecraft.world.level.biome.Biome;
import net.minecraft.world.level.block.AbstractCauldronBlock;
import net.minecraft.world.level.block.Block;
import net.minecraft.world.level.block.LayeredCauldronBlock;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.level.material.Fluid;
import net.minecraft.world.phys.BlockHitResult;
import net.minecraft.world.phys.shapes.VoxelShape;

/**
 * The cauldron of a fluid, {@code <ns>:<path>_cauldron} (ADR 0108 D2 and its amendment after B525): vanilla's cauldron
 * classes with an empty interaction dispatcher and their own {@code useItemOn} ({@link FluidCauldrons#useOnCauldron}).
 * {@link Layered} has levels 1 to 3; {@link Full} is full only, as lava's. Both fire the fluid's {@code on_entity_inside},
 * drop a vanilla cauldron when broken and pick as a cauldron.
 */
public sealed interface ModCauldronBlock permits ModCauldronBlock.Layered, ModCauldronBlock.Full {
    /** The interaction dispatcher every cauldron here gets: empty, so vanilla's own interactions never run on it. */
    CauldronInteraction.Dispatcher NO_INTERACTIONS = new CauldronInteraction.Dispatcher();

    /** The fluid this cauldron holds. */
    FluidRegistry.Entry fluid();

    /** The state of this cauldron when full: level 3 for a layered one. */
    BlockState fullState();

    /** Whether {@code state} of this cauldron is full. */
    boolean isFullState(BlockState state);

    /** The cauldron with three levels (water-like or {@code none} fluids with {@code levels}). */
    final class Layered extends LayeredCauldronBlock implements ModCauldronBlock {
        private final FluidRegistry.Entry fluid;

        Layered(Properties properties, FluidRegistry.Entry fluid) {
            super(Biome.Precipitation.NONE, NO_INTERACTIONS, properties);
            this.fluid = fluid;
        }

        @Override
        public FluidRegistry.Entry fluid() {
            return fluid;
        }

        @Override
        public BlockState fullState() {
            return defaultBlockState().setValue(LEVEL, MAX_FILL_LEVEL);
        }

        @Override
        public boolean isFullState(BlockState state) {
            return state.is(this) && state.getValue(LEVEL) == MAX_FILL_LEVEL;
        }

        @Override
        protected InteractionResult useItemOn(ItemStack stack, BlockState state, Level level, BlockPos pos, Player player, InteractionHand hand,
                BlockHitResult hit) {
            InteractionResult ours = FluidCauldrons.useOnCauldron(this, stack, state, level, pos, player, hand);
            return ours != null ? ours : super.useItemOn(stack, state, level, pos, player, hand, hit);
        }

        @Override
        protected void entityInside(BlockState state, Level level, BlockPos pos, Entity entity, InsideBlockEffectApplier effects, boolean intersects) {
            if (fluid.spec().behavesLike() == FluidSpec.Behaviour.WATER) {
                super.entityInside(state, level, pos, entity, effects, intersects);
            }
            if (intersects) {
                fluid.block().fireInside(level, pos, entity);
            }
        }

        @Override
        public void handlePrecipitation(BlockState state, Level level, BlockPos pos, Biome.Precipitation precipitation) {
            // Rain and snow never fill these cauldrons.
        }

        @Override
        protected boolean canReceiveStalactiteDrip(Fluid dripping) {
            return false;
        }

        @Override
        protected ItemStack getCloneItemStack(LevelReader level, BlockPos pos, BlockState state, boolean includeData) {
            return new ItemStack(Items.CAULDRON);
        }
    }

    /** The full-only cauldron (lava-like fluids, and any fluid without {@code levels}). */
    final class Full extends AbstractCauldronBlock implements ModCauldronBlock {
        /** How high the contents reach, in blocks (fifteen sixteenths). */
        static final double CONTENT_HEIGHT = 15.0 / 16.0;
        /** The space inside the walls up to the contents: where an entity is in the fluid. */
        private static final VoxelShape INSIDE = Block.box(2.0, FLOOR_LEVEL, 2.0, 14.0, 15.0, 14.0);

        private final FluidRegistry.Entry fluid;

        Full(Properties properties, FluidRegistry.Entry fluid) {
            super(properties, NO_INTERACTIONS);
            this.fluid = fluid;
        }

        @Override
        public FluidRegistry.Entry fluid() {
            return fluid;
        }

        @Override
        public BlockState fullState() {
            return defaultBlockState();
        }

        @Override
        public boolean isFullState(BlockState state) {
            return state.is(this);
        }

        @Override
        public boolean isFull(BlockState state) {
            return true;
        }

        @Override
        protected double getContentHeight(BlockState state) {
            return CONTENT_HEIGHT;
        }

        @Override
        protected int getAnalogOutputSignal(BlockState state, Level level, BlockPos pos, Direction direction) {
            return LayeredCauldronBlock.MAX_FILL_LEVEL;
        }

        @Override
        protected VoxelShape getEntityInsideCollisionShape(BlockState state, BlockGetter level, BlockPos pos, Entity entity) {
            return INSIDE;
        }

        @Override
        protected InteractionResult useItemOn(ItemStack stack, BlockState state, Level level, BlockPos pos, Player player, InteractionHand hand,
                BlockHitResult hit) {
            InteractionResult ours = FluidCauldrons.useOnCauldron(this, stack, state, level, pos, player, hand);
            return ours != null ? ours : super.useItemOn(stack, state, level, pos, player, hand, hit);
        }

        @Override
        protected void entityInside(BlockState state, Level level, BlockPos pos, Entity entity, InsideBlockEffectApplier effects, boolean intersects) {
            if (intersects) {
                FluidRegistry.insideEffects(fluid.spec(), effects);
                fluid.block().fireInside(level, pos, entity);
            }
        }

        @Override
        protected boolean canReceiveStalactiteDrip(Fluid dripping) {
            return false;
        }

        @Override
        protected ItemStack getCloneItemStack(LevelReader level, BlockPos pos, BlockState state, boolean includeData) {
            return new ItemStack(Items.CAULDRON);
        }
    }
}
`;
}

/** `fluid/ModBottleItem.java`: the runtime's `MsmBottleItem`. */
export function modBottleItemJava(fluidPackage: string): string {
  return `// Generated by MCSuperMods: msm_runtime's MsmBottleItem as a plain class.
package ${fluidPackage};

import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.entity.LivingEntity;
import net.minecraft.world.item.Item;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.level.Level;

/**
 * The bottle of a fluid, {@code <ns>:<path>_bottle} (ADR 0108 D3): a drink that leaves a glass bottle. Drinking it to the
 * end fires the fluid's {@code bottle.on_drink} on the server, after vanilla has applied the food and effects, with the
 * drinker as self; an interrupted drink fires nothing.
 */
public final class ModBottleItem extends Item {
    private final FluidSpec spec;

    ModBottleItem(Properties properties, FluidSpec spec) {
        super(properties);
        this.spec = spec;
    }

    @Override
    public ItemStack finishUsingItem(ItemStack stack, Level level, LivingEntity entity) {
        ItemStack result = super.finishUsingItem(stack, level, entity);
        if (spec.drink() != null && level instanceof ServerLevel server) {
            spec.drink().fire(server, entity);
        }
        return result;
    }
}
`;
}

/** `fluid/FluidCauldrons.java`: the runtime's `MsmCauldrons`. */
export function fluidCauldronsJava(fluidPackage: string, modId: string): string {
  return `// Generated by MCSuperMods: msm_runtime's MsmCauldrons as a plain helper.
package ${fluidPackage};

import java.util.IdentityHashMap;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Optional;
import net.fabricmc.fabric.api.creativetab.v1.CreativeModeTabEvents;
import net.fabricmc.fabric.api.event.player.UseBlockCallback;
import net.fabricmc.fabric.api.event.player.UseItemCallback;
import net.minecraft.core.BlockPos;
import net.minecraft.core.Holder;
import net.minecraft.core.Registry;
import net.minecraft.core.cauldron.CauldronInteractions;
import net.minecraft.core.component.DataComponents;
import net.minecraft.core.registries.BuiltInRegistries;
import net.minecraft.core.registries.Registries;
import net.minecraft.resources.Identifier;
import net.minecraft.resources.ResourceKey;
import net.minecraft.sounds.SoundEvent;
import net.minecraft.sounds.SoundEvents;
import net.minecraft.sounds.SoundSource;
import net.minecraft.stats.Stats;
import net.minecraft.world.InteractionHand;
import net.minecraft.world.InteractionResult;
import net.minecraft.world.effect.MobEffect;
import net.minecraft.world.effect.MobEffectInstance;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.food.FoodProperties;
import net.minecraft.world.item.CreativeModeTab;
import net.minecraft.world.item.Item;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.item.ItemUseAnimation;
import net.minecraft.world.item.ItemUtils;
import net.minecraft.world.item.Items;
import net.minecraft.world.item.component.Consumable;
import net.minecraft.world.item.consume_effects.ApplyStatusEffectsConsumeEffect;
import net.minecraft.world.level.ClipContext;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.block.Block;
import net.minecraft.world.level.block.Blocks;
import net.minecraft.world.level.block.LayeredCauldronBlock;
import net.minecraft.world.level.block.state.BlockBehaviour;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.level.gameevent.GameEvent;
import net.minecraft.world.level.material.FluidState;
import net.minecraft.world.phys.BlockHitResult;
import net.minecraft.world.phys.HitResult;
import net.minecraft.world.phys.Vec3;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * Cauldrons and bottles of the fluids (ADR 0108 D2, D3 and the amendment after B525), with no Mixin: per fluid with a
 * cauldron, the block {@code <ns>:<path>_cauldron} ({@link ModCauldronBlock}); with a bottle, the item
 * {@code <ns>:<path>_bottle} ({@link ModBottleItem}, stacks of 16, in vanilla's Food and Drinks tab). On a fluid's cauldron
 * an empty bucket takes a full one, a bucket of a liquid with a cauldron replaces its contents, and on a layered one a
 * glass bottle takes a level and the fluid's bottle adds one; a fluid's bucket or bottle also works on vanilla's
 * cauldrons, and a glass bottle used on a source of a fluid with a bottle fills with it. Both callbacks skip spectators
 * and sneaking players with an item in hand.
 */
public final class FluidCauldrons {
    private static final Logger LOGGER = LoggerFactory.getLogger(${javaString(modId)});
    /** The vanilla tab the bottles join (vanilla's potions are there). */
    static final ResourceKey<CreativeModeTab> BOTTLE_TAB =
            ResourceKey.create(Registries.CREATIVE_MODE_TAB, Identifier.withDefaultNamespace("food_and_drinks"));
    /** How many bottles stack. */
    public static final int BOTTLE_STACK = 16;

    private FluidCauldrons() {}

    /** The companions of one fluid; {@code cauldron} and {@code bottle} may be null. */
    public record Companions(FluidRegistry.Entry fluid, ModCauldronBlock cauldron, ModBottleItem bottle) {}

    private static final Map<Identifier, Companions> BY_FLUID = new LinkedHashMap<>();
    private static final Map<Item, Companions> BY_BUCKET = new IdentityHashMap<>();
    private static final Map<Item, Companions> BY_BOTTLE = new IdentityHashMap<>();
    private static final Map<Block, Companions> BY_LIQUID = new IdentityHashMap<>();
    private static boolean installed;

    /**
     * Registers the cauldron blocks and bottle items of the registered fluids and installs the use callbacks; runs once,
     * after every block and item.
     */
    public static void register() {
        for (FluidRegistry.Entry entry : FluidRegistry.registered()) {
            FluidSpec spec = entry.spec();
            if ((spec.cauldron() == null && spec.bottle() == null) || BY_FLUID.containsKey(entry.id())) {
                continue;
            }
            ModCauldronBlock cauldron = null;
            if (spec.cauldron() != null) {
                Identifier id = entry.id().withSuffix("_cauldron");
                if (BuiltInRegistries.BLOCK.containsKey(id)) {
                    LOGGER.error("fluid {}: cauldron: block id {} is already registered; the cauldron is not registered", entry.id(), id);
                } else {
                    cauldron = registerCauldron(id, entry);
                }
            }
            ModBottleItem bottle = null;
            if (spec.bottle() != null) {
                Identifier id = entry.id().withSuffix("_bottle");
                if (BuiltInRegistries.ITEM.containsKey(id)) {
                    LOGGER.error("fluid {}: bottle: item id {} is already registered; the bottle is not registered", entry.id(), id);
                } else {
                    bottle = registerBottle(id, entry, spec.bottle());
                }
            }
            if (cauldron == null && bottle == null) {
                continue;
            }
            Companions companions = new Companions(entry, cauldron, bottle);
            BY_FLUID.put(entry.id(), companions);
            BY_LIQUID.put(entry.block(), companions);
            if (cauldron != null) {
                BY_BUCKET.put(entry.bucket(), companions);
            }
            if (bottle != null) {
                BY_BOTTLE.put(bottle, companions);
            }
        }
        if (!installed) {
            installed = true;
            UseBlockCallback.EVENT.register(FluidCauldrons::useOnVanillaCauldron);
            UseItemCallback.EVENT.register(FluidCauldrons::useGlassBottle);
        }
    }

    private static ModCauldronBlock registerCauldron(Identifier id, FluidRegistry.Entry entry) {
        ResourceKey<Block> key = ResourceKey.create(Registries.BLOCK, id);
        int light = entry.spec().light();
        BlockBehaviour.Properties props = BlockBehaviour.Properties.ofLegacyCopy(Blocks.CAULDRON)
                .setId(key)
                .overrideLootTable(Blocks.CAULDRON.getLootTable())
                .lightLevel(state -> light);
        boolean levels = entry.spec().cauldron().levels() && entry.spec().behavesLike() != FluidSpec.Behaviour.LAVA;
        Block block = levels ? new ModCauldronBlock.Layered(props, entry) : new ModCauldronBlock.Full(props, entry);
        return (ModCauldronBlock) Registry.register(BuiltInRegistries.BLOCK, key, block);
    }

    private static ModBottleItem registerBottle(Identifier id, FluidRegistry.Entry entry, FluidSpec.Bottle spec) {
        ResourceKey<Item> key = ResourceKey.create(Registries.ITEM, id);
        Consumable.Builder drink = Consumable.builder()
                .consumeSeconds(FluidSpec.BOTTLE_DRINK_SECONDS)
                .animation(ItemUseAnimation.DRINK)
                .sound(SoundEvents.GENERIC_DRINK)
                .hasConsumeParticles(false);
        for (FluidSpec.Effect effect : spec.effects()) {
            Optional<Holder.Reference<MobEffect>> holder = BuiltInRegistries.MOB_EFFECT.get(effect.effect());
            if (holder.isEmpty()) {
                LOGGER.error("fluid {}: bottle: effects: unknown mob effect {}; the effect is left out", entry.id(), effect.effect());
                continue;
            }
            drink = drink.onConsume(new ApplyStatusEffectsConsumeEffect(new MobEffectInstance(holder.get(), effect.ticks(), effect.amplifier()),
                    effect.chance()));
        }
        Item.Properties props = new Item.Properties().setId(key).stacksTo(BOTTLE_STACK).usingConvertsTo(Items.GLASS_BOTTLE);
        if (spec.food() != null) {
            FluidSpec.Food food = spec.food();
            props = props.food(new FoodProperties(food.nutrition(), food.saturation(), food.canAlwaysEat()), drink.build());
        } else {
            props = props.component(DataComponents.CONSUMABLE, drink.build());
        }
        ModBottleItem bottle = Registry.register(BuiltInRegistries.ITEM, key, new ModBottleItem(props, entry.spec()));
        CreativeModeTabEvents.modifyOutputEvent(BOTTLE_TAB).register(output -> output.accept(bottle));
        return bottle;
    }

    /** The sound a bucket of the fluid makes emptying: lava's for lava-like, else water's. */
    static SoundEvent emptySound(FluidSpec spec) {
        return spec.behavesLike() == FluidSpec.Behaviour.LAVA ? SoundEvents.BUCKET_EMPTY_LAVA : SoundEvents.BUCKET_EMPTY;
    }

    /** A bucket that empties into a cauldron: the full cauldron it makes and the sound, or null for any other item. */
    private record Pour(BlockState into, SoundEvent sound) {}

    private static Pour pourOf(ItemStack stack) {
        if (stack.is(Items.WATER_BUCKET)) {
            return new Pour(Blocks.WATER_CAULDRON.defaultBlockState().setValue(LayeredCauldronBlock.LEVEL, LayeredCauldronBlock.MAX_FILL_LEVEL),
                    SoundEvents.BUCKET_EMPTY);
        }
        if (stack.is(Items.LAVA_BUCKET)) {
            return new Pour(Blocks.LAVA_CAULDRON.defaultBlockState(), SoundEvents.BUCKET_EMPTY_LAVA);
        }
        return projectPour(stack);
    }

    private static Pour projectPour(ItemStack stack) {
        Companions c = stack.isEmpty() ? null : BY_BUCKET.get(stack.getItem());
        return c == null || c.cauldron() == null ? null : new Pour(c.cauldron().fullState(), emptySound(c.fluid().spec()));
    }

    /** A fluid cauldron's own interactions; null when {@code stack} is none of them. */
    static InteractionResult useOnCauldron(ModCauldronBlock cauldron, ItemStack stack, BlockState state, Level level, BlockPos pos,
            Player player, InteractionHand hand) {
        FluidRegistry.Entry fluid = cauldron.fluid();
        if (stack.is(Items.BUCKET)) {
            return CauldronInteractions.fillBucket(state, level, pos, player, hand, stack, new ItemStack(fluid.bucket()), cauldron::isFullState,
                    FluidRegistry.pickupSound(fluid.spec()));
        }
        Pour pour = pourOf(stack);
        if (pour != null) {
            return CauldronInteractions.emptyBucket(level, pos, player, hand, stack, pour.into(), pour.sound());
        }
        if (!(cauldron instanceof ModCauldronBlock.Layered)) {
            return null;
        }
        Companions companions = BY_FLUID.get(fluid.id());
        ModBottleItem bottle = companions == null ? null : companions.bottle();
        if (bottle == null) {
            return null;
        }
        int lvl = state.getValue(LayeredCauldronBlock.LEVEL);
        if (stack.is(Items.GLASS_BOTTLE)) {
            if (!level.isClientSide()) {
                player.setItemInHand(hand, ItemUtils.createFilledResult(stack, player, new ItemStack(bottle)));
                player.awardStat(Stats.USE_CAULDRON);
                player.awardStat(Stats.ITEM_USED.get(stack.getItem()));
                LayeredCauldronBlock.lowerFillLevel(state, level, pos);
                level.playSound(null, pos, SoundEvents.BOTTLE_FILL, SoundSource.BLOCKS, 1.0f, 1.0f);
                level.gameEvent(null, GameEvent.FLUID_PICKUP, pos);
            }
            return InteractionResult.SUCCESS;
        }
        if (stack.is(bottle) && lvl < LayeredCauldronBlock.MAX_FILL_LEVEL) {
            if (!level.isClientSide()) {
                player.setItemInHand(hand, ItemUtils.createFilledResult(stack, player, new ItemStack(Items.GLASS_BOTTLE)));
                player.awardStat(Stats.USE_CAULDRON);
                player.awardStat(Stats.ITEM_USED.get(stack.getItem()));
                level.setBlockAndUpdate(pos, state.setValue(LayeredCauldronBlock.LEVEL, lvl + 1));
                level.playSound(null, pos, SoundEvents.BOTTLE_EMPTY, SoundSource.BLOCKS, 1.0f, 1.0f);
                level.gameEvent(null, GameEvent.FLUID_PLACE, pos);
            }
            return InteractionResult.SUCCESS;
        }
        return null;
    }

    /** Whether the player's use skips the block, as vanilla's: spectators, and sneaking with an item in hand. */
    private static boolean skipsBlocks(Player player) {
        return player.isSpectator() || (player.isSecondaryUseActive() && (!player.getMainHandItem().isEmpty() || !player.getOffhandItem().isEmpty()));
    }

    private static boolean isVanillaCauldron(BlockState state) {
        return state.is(Blocks.CAULDRON) || state.is(Blocks.WATER_CAULDRON) || state.is(Blocks.LAVA_CAULDRON) || state.is(Blocks.POWDER_SNOW_CAULDRON);
    }

    /** A fluid's bucket or bottle on one of vanilla's cauldrons. */
    static InteractionResult useOnVanillaCauldron(Player player, Level level, InteractionHand hand, BlockHitResult hit) {
        if (BY_FLUID.isEmpty() || skipsBlocks(player)) {
            return InteractionResult.PASS;
        }
        BlockPos pos = hit.getBlockPos();
        BlockState state = level.getBlockState(pos);
        if (!isVanillaCauldron(state)) {
            return InteractionResult.PASS;
        }
        ItemStack stack = player.getItemInHand(hand);
        Pour pour = projectPour(stack);
        if (pour != null) {
            return CauldronInteractions.emptyBucket(level, pos, player, hand, stack, pour.into(), pour.sound());
        }
        Companions c = stack.isEmpty() ? null : BY_BOTTLE.get(stack.getItem());
        if (c != null && state.is(Blocks.CAULDRON) && c.cauldron() instanceof ModCauldronBlock.Layered layered) {
            if (!level.isClientSide()) {
                player.setItemInHand(hand, ItemUtils.createFilledResult(stack, player, new ItemStack(Items.GLASS_BOTTLE)));
                player.awardStat(Stats.USE_CAULDRON);
                player.awardStat(Stats.ITEM_USED.get(stack.getItem()));
                level.setBlockAndUpdate(pos, layered.defaultBlockState().setValue(LayeredCauldronBlock.LEVEL, 1));
                level.playSound(null, pos, SoundEvents.BOTTLE_EMPTY, SoundSource.BLOCKS, 1.0f, 1.0f);
                level.gameEvent(null, GameEvent.FLUID_PLACE, pos);
            }
            return InteractionResult.SUCCESS;
        }
        return InteractionResult.PASS;
    }

    /** A glass bottle used on a source of a fluid with a bottle: the fluid's bottle instead of vanilla's water bottle. */
    static InteractionResult useGlassBottle(Player player, Level level, InteractionHand hand) {
        ItemStack stack = player.getItemInHand(hand);
        if (BY_BOTTLE.isEmpty() || player.isSpectator() || !stack.is(Items.GLASS_BOTTLE)) {
            return InteractionResult.PASS;
        }
        Vec3 eye = player.getEyePosition();
        Vec3 to = eye.add(player.getViewVector(1.0f).scale(player.blockInteractionRange()));
        BlockHitResult hit = level.clip(new ClipContext(eye, to, ClipContext.Block.OUTLINE, ClipContext.Fluid.SOURCE_ONLY, player));
        if (hit.getType() != HitResult.Type.BLOCK) {
            return InteractionResult.PASS;
        }
        BlockPos pos = hit.getBlockPos();
        FluidState fluid = level.getFluidState(pos);
        if (fluid.isEmpty() || !fluid.isSource() || !level.mayInteract(player, pos)) {
            return InteractionResult.PASS;
        }
        Companions c = BY_LIQUID.get(fluid.createLegacyBlock().getBlock());
        if (c == null || c.bottle() == null) {
            return InteractionResult.PASS;
        }
        if (!level.isClientSide()) {
            player.setItemInHand(hand, ItemUtils.createFilledResult(stack, player, new ItemStack(c.bottle())));
            player.awardStat(Stats.ITEM_USED.get(stack.getItem()));
            level.playSound(null, player.getX(), player.getY(), player.getZ(), SoundEvents.BOTTLE_FILL, SoundSource.NEUTRAL, 1.0f, 1.0f);
            level.gameEvent(player, GameEvent.FLUID_PICKUP, pos);
        }
        return InteractionResult.SUCCESS;
    }
}
`;
}

/** `client/fluid/FluidRenderers.java`: the runtime's `FluidClient`, reading the pictures from this mod. */
export function fluidRenderersJava(
  clientFluidPackage: string,
  fluidPackage: string,
  modId: string,
): string {
  return `// Generated by MCSuperMods: msm_runtime's FluidClient as a plain helper.
package ${clientFluidPackage};

import ${fluidPackage}.FluidRegistry;
import ${fluidPackage}.FluidSpec;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import java.io.IOException;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Optional;
import net.fabricmc.fabric.api.client.render.fluid.v1.FluidRenderingRegistry;
import net.fabricmc.loader.api.FabricLoader;
import net.fabricmc.loader.api.ModContainer;
import net.minecraft.client.color.block.BlockTintSource;
import net.minecraft.client.renderer.block.FluidModel;
import net.minecraft.client.resources.model.sprite.Material;
import net.minecraft.resources.Identifier;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * The fluids' renderers (ADR 0099 D2 and its amendment): one {@code FluidModel.Unbaked} per fluid through Fabric's
 * {@code FluidRenderingRegistry} for the still and the flowing fluid, with the still, flowing and optional overlay
 * pictures named in the liquid block's model ({@code assets/<ns>/models/block/<path>.json}, texture variables
 * {@code still}, {@code flowing} and {@code overlay}) and the fluid's tint. A model without them falls back to vanilla's
 * water pictures (lava's for a lava-like fluid) and no overlay.
 */
public final class FluidRenderers {
    private static final String MOD_ID = ${javaString(modId)};
    private static final Logger LOGGER = LoggerFactory.getLogger(MOD_ID);

    private FluidRenderers() {}

    /** The sprite ids a fluid is drawn with. {@code overlay} is null for none. */
    record Pictures(Identifier still, Identifier flowing, Identifier overlay) {}

    /** Registers the renderers of the fluids; called from the client entrypoint. */
    public static void init() {
        for (FluidRegistry.Entry entry : FluidRegistry.registered()) {
            try {
                Pictures pictures = pictures(entry);
                BlockTintSource tint = entry.spec().tint() < 0 ? null : tint(entry.spec().tint());
                FluidModel.Unbaked model = new FluidModel.Unbaked(new Material(pictures.still()), new Material(pictures.flowing()),
                        pictures.overlay() == null ? null : new Material(pictures.overlay()), tint);
                FluidRenderingRegistry.register(entry.fluids().still(), entry.fluids().flowing(), model);
            } catch (RuntimeException e) {
                LOGGER.error("fluid {}: could not register its renderer", entry.id(), e);
            }
        }
    }

    /** A tint that multiplies the pictures by the RGB colour {@code rgb} wherever the fluid is. */
    static BlockTintSource tint(int rgb) {
        int colour = rgb & 0xFFFFFF;
        return state -> colour;
    }

    /** The pictures of a fluid: from its liquid block's model, else vanilla's. */
    static Pictures pictures(FluidRegistry.Entry entry) {
        boolean lava = entry.spec().behavesLike() == FluidSpec.Behaviour.LAVA;
        Identifier still = Identifier.withDefaultNamespace(lava ? "block/lava_still" : "block/water_still");
        Identifier flowing = Identifier.withDefaultNamespace(lava ? "block/lava_flow" : "block/water_flow");
        Identifier overlay = null;
        Optional<JsonObject> textures = modelTextures(entry.id());
        if (textures.isPresent()) {
            still = texture(textures.get(), "still").orElse(still);
            flowing = texture(textures.get(), "flowing").orElse(flowing);
            overlay = texture(textures.get(), "overlay").orElse(null);
        } else {
            LOGGER.warn("fluid {}: no textures in assets/{}/models/block/{}.json; vanilla's {} pictures are used",
                    entry.id(), entry.id().getNamespace(), entry.id().getPath(), lava ? "lava" : "water");
        }
        return new Pictures(still, flowing, overlay);
    }

    /** A texture variable that names a picture (not a {@code #reference}), as a sprite id. */
    private static Optional<Identifier> texture(JsonObject textures, String name) {
        JsonElement value = textures.get(name);
        if (value == null || !value.isJsonPrimitive() || !value.getAsJsonPrimitive().isString()) {
            return Optional.empty();
        }
        String text = value.getAsString();
        return text.startsWith("#") ? Optional.empty() : Optional.ofNullable(Identifier.tryParse(text));
    }

    /** The {@code textures} object of the liquid block's model in this mod, if it has one. */
    private static Optional<JsonObject> modelTextures(Identifier id) {
        Optional<ModContainer> mod = FabricLoader.getInstance().getModContainer(MOD_ID);
        if (mod.isEmpty()) {
            return Optional.empty();
        }
        Optional<Path> file = mod.get().findPath("assets/" + id.getNamespace() + "/models/block/" + id.getPath() + ".json");
        if (file.isEmpty() || !Files.isRegularFile(file.get())) {
            return Optional.empty();
        }
        try (Reader reader = Files.newBufferedReader(file.get(), StandardCharsets.UTF_8)) {
            JsonElement json = JsonParser.parseReader(reader);
            if (json.isJsonObject() && json.getAsJsonObject().get("textures") instanceof JsonObject textures) {
                return Optional.of(textures);
            }
        } catch (IOException | RuntimeException e) {
            LOGGER.warn("fluid {}: could not read its block model: {}", id, e.getMessage());
        }
        return Optional.empty();
    }
}
`;
}
